    return StatementLine(ref="S-x", date="2026-03-%02d" % day, description="x", amount_cents=amount)


def test_exact_amounts_match():
    result = match_entries([_entry(1000)], [_line(1000)], tolerance_cents=2)
    assert len(result.pairs) == 1


